select
student.*
from student student

    and student.id = #{id}
    and student.stu_name like concat('%',#{stuName},'%')
    and student.stu_age = #{stuAge}
    and student.stu_sex = #{stuSex}
    and student.stu_phone = #{stuPhone}
    and student.stu_address = #{stuAddress}
    and student.stu_class_num = #{stuClassNum}
    and student.stu_img = #{stuImg}
    and student.password = #{password}
    and student.status = #{status}


    limit #{current},#{pageSize}

select count(*) from student student

    and student.id = #{id}
    and student.stu_name like concat('%',#{stuName},'%')
    and student.stu_age = #{stuAge}
    and student.stu_sex = #{stuSex}
    and student.stu_phone = #{stuPhone}
    and student.stu_address = #{stuAddress}
    and student.stu_class_num = #{stuClassNum}
    and student.stu_img = #{stuImg}
    and student.password = #{password}
    and student.status = #{status}
